package build

import (
	"fmt"
	"strings"

	"mochi/package3/java/maven"
)

// POMDependency is a single Maven dependency in a generated POM.
type POMDependency struct {
	GroupID    string
	ArtifactID string
	Version    string
	// Scope defaults to "compile" when empty.
	Scope string
}

// POMSpec configures the POM generated by RenderPOM.
type POMSpec struct {
	// GroupID, ArtifactID, Version identify the published artifact.
	GroupID    string
	ArtifactID string
	Version    string

	// Name is the human-readable project name (optional).
	Name string
	// Description is the project description (optional).
	Description string

	// Dependencies lists the upstream JARs this wrapper depends on at runtime.
	Dependencies []POMDependency
}

// RenderPOM generates a minimal Maven POM XML string from the spec.
func RenderPOM(spec POMSpec) string {
	var b strings.Builder
	b.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
	b.WriteString(`<project xmlns="http://maven.apache.org/POM/4.0.0"`)
	b.WriteString(`         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"`)
	b.WriteString(`         xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd">`)
	b.WriteString("\n  <modelVersion>4.0.0</modelVersion>\n")
	fmt.Fprintf(&b, "  <groupId>%s</groupId>\n", xmlEscape(spec.GroupID))
	fmt.Fprintf(&b, "  <artifactId>%s</artifactId>\n", xmlEscape(spec.ArtifactID))
	fmt.Fprintf(&b, "  <version>%s</version>\n", xmlEscape(spec.Version))
	if spec.Name != "" {
		fmt.Fprintf(&b, "  <name>%s</name>\n", xmlEscape(spec.Name))
	}
	if spec.Description != "" {
		fmt.Fprintf(&b, "  <description>%s</description>\n", xmlEscape(spec.Description))
	}
	if len(spec.Dependencies) > 0 {
		b.WriteString("  <dependencies>\n")
		for _, d := range spec.Dependencies {
			scope := d.Scope
			if scope == "" {
				scope = "compile"
			}
			b.WriteString("    <dependency>\n")
			fmt.Fprintf(&b, "      <groupId>%s</groupId>\n", xmlEscape(d.GroupID))
			fmt.Fprintf(&b, "      <artifactId>%s</artifactId>\n", xmlEscape(d.ArtifactID))
			fmt.Fprintf(&b, "      <version>%s</version>\n", xmlEscape(d.Version))
			fmt.Fprintf(&b, "      <scope>%s</scope>\n", xmlEscape(scope))
			b.WriteString("    </dependency>\n")
		}
		b.WriteString("  </dependencies>\n")
	}
	b.WriteString("</project>\n")
	return b.String()
}

// WrapperPOMSpec returns a POMSpec for the JNI wrapper library generated for
// an upstream Maven coordinate. The wrapper artifact is placed in the
// "dev.mochi.java-bridge" group and depends on the upstream JAR.
func WrapperPOMSpec(upstream maven.Coordinate) POMSpec {
	artID := strings.ReplaceAll(upstream.GroupID, ".", "-") + "-" + upstream.ArtifactID + "-jni-wrapper"
	return POMSpec{
		GroupID:    "dev.mochi.java-bridge",
		ArtifactID: artID,
		Version:    upstream.Version,
		Name:       upstream.ArtifactID + " JNI wrapper",
		Description: "Auto-generated JNI wrapper for " + upstream.String() + " produced by the Mochi Java bridge (MEP-67).",
		Dependencies: []POMDependency{
			{GroupID: upstream.GroupID, ArtifactID: upstream.ArtifactID, Version: upstream.Version},
		},
	}
}

